use super::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use semio_framework_value_native_decoding::native_decoding::{OriginalEffectAuthority,OriginalEffectProducer,OriginalEffectReply,OriginalEffectReplyComplete};

fn no_fields(_:usize)->Option<NativeRecordSchema>{None}
#[derive(Clone,Copy)]enum Operation{Start,Close,KeyBirth}
struct Producer<'owner>{owner:&'owner mut NativeRecordMatcher<dyn NativeValueSource>}
impl OriginalEffectProducer for Producer<'_>{
 type Output=RetainedCloneStep;type Failure=semio_framework_value_retirement::OriginalRetirementFailure;type Context<'a,'b>=(Operation,crate::OriginalSourceTurnWitness<'a>) where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,context:&Self::Context<'a,'b>)->Option<crate::OriginalSourceTurnIdentity>where 'b:'a{Some(context.1.identity())}
 fn receive<'r,'a,'b>(&mut self,operation:&mut Self::Context<'a,'b>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{match operation.0{Operation::Start=>{let turn=self.owner.begin_close_paid(effect);Ok(reply.complete(turn.result.map_err(Into::into)))},Operation::Close=>self.owner.close_into(4096,effect,reply),Operation::KeyBirth=>self.owner.key_birth_retirement_into(effect,reply)}}
 fn recover<'r,'a,'b>(&mut self,operation:&mut Self::Context<'a,'b>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{match operation.0{Operation::Close=>self.owner.recover_close_into(4096,effect,reply),Operation::Start|Operation::KeyBirth=>Ok(reply.pending())}}
}
fn drive(bank:&mut EffectBank,authority:&mut OriginalEffectAuthority<Producer<'_>>,operation:Operation,grant:RetainedCloneGrant)->(RetainedCloneStep,u128,Option<usize>,Option<bool>){let mut action=None;let((poll,actual),heap)=observe(||bank.run_with_source(grant,1,|effect,witness|{let before=effect.performed_work();let mut context=(operation,witness);let ready=authority.drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{crate::RetainedWorkPoll::Pending{work}}}));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("matcher operation remained pending")};turn.result.unwrap();let progress=action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap().progress();let admitted=bank.take_admitted();if let Some(bytes)=actual{assert_eq!(bytes,heap.0)}bank.post(progress,grant,heap);let demand=OriginalEffectAuthority::<Producer<'_>>::transfer_reply_demand().unwrap();assert!(demand.copy_bytes<=4096,"original matcher reply transfer exceeds 4096");let transfer=bank.loan(1,demand.copy_bytes);let mut output=None;let(poll,actual_transfer)=bank.run_with_source(transfer,1,|effect,witness|crate::RetainedWorkPoll::Complete(authority.transfer_reply_into(&(operation,witness),&mut action,&mut output,effect)));let crate::RetainedWorkPoll::Complete(paid)=poll else{panic!("matcher reply transfer remained pending")};let transferred=paid.result.unwrap().unwrap();assert_eq!(actual_transfer,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(transferred,transfer,(0,0));assert!(action.is_none());(output.unwrap().unwrap(),turn.work,actual,admitted)}
#[test]
fn original_matcher_frame_waits_for_its_funded_header_clear(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️close.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeRecordMatcher::<dyn NativeValueSource>::new(unsafe{NativeSchemaFields::native(no_fields)},0,NativeSchemaKeySource::Text);owner.pending=Some(SchemaFrame{fields:unsafe{NativeSchemaFields::native(no_fields)},count:0,index:0,root:None,role:0,before:NativeFieldMatch::Missing,best:NativeFieldMatch::Missing});let mut authority=Some(OriginalEffectAuthority::new(Producer{owner:&mut owner}));let start=authority.as_ref().unwrap().inspect(|p|p.owner.begin_close_demand());let denied_start=bank.loan(1,0);let(step,work,actual,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::Start,denied_start);assert_eq!(work,0);assert!(!authority.as_ref().unwrap().inspect(|p|p.owner.close_started()));assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(actual,None);assert_eq!(admitted,None);let grant=bank.loan(1,start.copy_bytes);let(step,work,actual,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::Start,grant);assert_eq!(work,u128::from(law["startWork"].as_u64().unwrap()));assert!(authority.as_ref().unwrap().inspect(|p|p.owner.close_started()));assert_eq!(actual,None);assert_eq!(admitted,Some(true));
 let demand=authority.as_ref().unwrap().inspect(|p|p.owner.close_demands(4096)).unwrap();assert!(demand.copy_bytes>0);let denied=bank.loan(1,demand.copy_bytes-1);let(step,work,actual,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::Close,denied);assert_eq!(work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(law["denied"],"completedNoProgress");assert!(authority.as_ref().unwrap().inspect(|p|p.owner.pending.is_some()));assert_eq!(actual,None);assert_eq!(admitted,None);
 let grant=bank.loan(1,demand.copy_bytes);let(step,work,actual,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::Close,grant);assert_eq!(work,u128::from(law["clearedWork"].as_u64().unwrap()));let progress=step.progress();assert_eq!(progress.copied_bytes,demand.copy_bytes);assert_eq!(law["cleared"],"backingFrame");assert!(authority.as_ref().unwrap().inspect(|p|p.owner.pending.is_none()));assert_eq!(actual,None);assert_eq!(admitted,Some(true));assert!(authority.as_ref().unwrap().inspect(|p|p.owner.terminal_is_empty()));
 let demand=OriginalEffectAuthority::<Producer<'_>>::producer_transfer_demand().unwrap();let grant=bank.loan(1,demand.copy_bytes);let mut returned=None;let(poll,actual)=bank.run_with_source(grant,1,|effect,witness|crate::RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&(Operation::Close,witness),&mut returned,effect)));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("producer return remained pending")};let progress=turn.result.unwrap().unwrap();assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,(0,0));assert!(authority.is_none());drop(returned.take().unwrap());
}

#[test]
fn pending_schema_page_denial_keeps_the_original_frame(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️close.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeRecordMatcher::<dyn NativeValueSource>::new(unsafe{NativeSchemaFields::native(no_fields)},0,NativeSchemaKeySource::Text);owner.pending=Some(SchemaFrame{fields:unsafe{NativeSchemaFields::native(no_fields)},count:0,index:0,root:None,role:0,before:NativeFieldMatch::Missing,best:NativeFieldMatch::Missing});let demand=owner.pending_slot_demand().unwrap();assert!(demand.capacity_bytes>0);let mut grant=bank.loan(1,demand.copy_bytes);grant.maximum_capacity_bytes=0;let work=owner.pending_slot_work_demand().unwrap();let mut reply=None;let(poll,actual)=bank.run(grant,work,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(owner.pending_slot_into(effect,token).unwrap());crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})});let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("unstarted page denial remained pending")};assert_eq!(turn.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(reply.as_ref().unwrap().as_ref().unwrap().progress(),RetainedCloneProgress::default());assert!(owner.pending.is_some());assert!(owner.frames.is_empty());assert_eq!(actual,None);assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),grant,(0,0));
 let mut authority=Some(OriginalEffectAuthority::new(Producer{owner:&mut owner}));let demand=authority.as_ref().unwrap().inspect(|p|p.owner.begin_close_demand());let grant=bank.loan(1,demand.copy_bytes);let(_,work,actual,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::Start,grant);assert_eq!(work,1);assert_eq!(actual,None);assert_eq!(admitted,Some(true));let demand=authority.as_ref().unwrap().inspect(|p|p.owner.close_demands(4096)).unwrap();let grant=bank.loan(1,demand.copy_bytes);let(_,work,actual,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::Close,grant);assert_eq!(work,1);assert_eq!(actual,None);assert_eq!(admitted,Some(true));assert!(authority.as_ref().unwrap().inspect(|p|p.owner.terminal_is_empty()));let demand=OriginalEffectAuthority::<Producer<'_>>::producer_transfer_demand().unwrap();let grant=bank.loan(1,demand.copy_bytes);let mut returned=None;let(poll,actual)=bank.run_with_source(grant,1,|effect,witness|crate::RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&(Operation::Close,witness),&mut returned,effect)));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("producer return remained pending")};let progress=turn.result.unwrap().unwrap();assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,(0,0));assert!(authority.is_none());drop(returned.take().unwrap());
}

fn exact_grant(bank:&EffectBank,demand:RetirementDemand,limit:usize)->RetainedCloneGrant{assert!(demand.copy_bytes<=limit,"native selected copy {} exceeds {}",demand.copy_bytes,limit);let mut grant=bank.loan(1,demand.copy_bytes);assert!(grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth);grant.maximum_capacity_bytes=demand.capacity_bytes;grant.maximum_release_bytes=demand.release_bytes;grant.maximum_depth=demand.depth;grant}
#[test]
fn key_backing_birth_cancels_at_every_native_seed_frontier(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🌳️source/🔣️key-query.json")).unwrap();let limit=law["maxPartCopy"].as_u64().unwrap() as usize;let maximum=law["seedStock"]["maximumTurns"].as_u64().unwrap() as usize;for cut in law["seedCancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap() as usize;let mut bank=EffectBank::new(Wallet::from_profile(&law["seedStock"]));let mut owner=NativeRecordMatcher::<dyn NativeValueSource>::new(unsafe{NativeSchemaFields::native(no_fields)},0,NativeSchemaKeySource::Text);let mut authority=Some(OriginalEffectAuthority::new(Producer{owner:&mut owner}));for phase in 0..cut{let demand=authority.as_ref().unwrap().inspect(|p|p.owner.key_birth_demand()).unwrap();assert_eq!(authority.as_ref().unwrap().inspect(|p|p.owner.key_birth_work_demand()).unwrap(),1);assert!(demand.copy_bytes<=limit,"cut {cut} birth phase {phase} quote {}",demand.copy_bytes);let grant=exact_grant(&bank,demand,limit);let(_,work,_,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::KeyBirth,grant);assert_eq!(work,1);assert_eq!(admitted,Some(true));}assert_eq!(authority.as_ref().unwrap().inspect(|p|p.owner.key_backing_initialized()),cut==law["seedParts"].as_u64().unwrap() as usize+2);let demand=authority.as_ref().unwrap().inspect(|p|p.owner.begin_close_demand());let grant=exact_grant(&bank,demand,limit);let(_,work,_,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::Start,grant);assert_eq!(work,1);assert_eq!(admitted,Some(true));for phase in 0..maximum{if authority.as_ref().unwrap().inspect(|p|p.owner.terminal_is_empty()){break}let demand=authority.as_ref().unwrap().inspect(|p|p.owner.close_demands(4096)).unwrap();assert_eq!(authority.as_ref().unwrap().inspect(|p|p.owner.close_work_demand(4096)).unwrap(),1);assert!(demand.copy_bytes<=limit,"cut {cut} close phase {phase} quote {}",demand.copy_bytes);let grant=exact_grant(&bank,demand,limit);let(_,work,_,admitted)=drive(&mut bank,authority.as_mut().unwrap(),Operation::Close,grant);assert_eq!(work,1);assert_eq!(admitted,Some(true));}assert!(authority.as_ref().unwrap().inspect(|p|p.owner.terminal_is_empty()));let demand=OriginalEffectAuthority::<Producer<'_>>::producer_transfer_demand().unwrap();let grant=exact_grant(&bank,demand,limit);let mut returned=None;let(poll,actual)=bank.run_with_source(grant,1,|effect,witness|crate::RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&(Operation::Close,witness),&mut returned,effect)));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("producer return remained pending")};let progress=turn.result.unwrap().unwrap();assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,(0,0));assert!(authority.is_none());drop(returned.take().unwrap());}
}
